from sheet import evaluate, CycleError

cases = [
    ({'A': '=2^3^2'}, {'A': 512.0}),
    ({'A': '=-2^2', 'B': '=(-2)^2'}, {'A': -4.0, 'B': 4.0}),
    ({'A': '=2^-2'}, {'A': 0.25}),
    ({'A': '=20/5/2'}, {'A': 2.0}),
    ({'A': '=-(1+2)*3'}, {'A': -9.0}),
    ({'A': '= B + 1 ', 'B': '3.5'}, {'A': 4.5, 'B': 3.5}),
    ({'A1': '=TOTAL+X12', 'TOTAL': '2', 'X12': '3'}, {'A1': 5.0, 'TOTAL': 2.0, 'X12': 3.0}),
]
for cells, expected in cases:
    actual = evaluate(cells)
    assert actual == expected, (actual, expected)

for cells in ({'A': '=A'}, {'A': '=B', 'B': '=C', 'C': '=A'}):
    try:
        evaluate(cells)
    except CycleError:
        pass
    else:
        raise AssertionError('cycle was not detected')

try:
    evaluate({'A': '=1/0'})
except ZeroDivisionError:
    pass
else:
    raise AssertionError('division by zero did not propagate')

